import openpyxl, zipfile
src='/root/data/workbook.xlsx'
out='/root/output/result.xlsx'
orig=openpyxl.load_workbook(src, data_only=False, keep_vba=False)
res=openpyxl.load_workbook(out, data_only=False, keep_vba=False)
errors=[]
if res.sheetnames != ['Task','Data']:
    errors.append(f'sheets={res.sheetnames}')
for s in orig.sheetnames:
    ow, rw = orig[s], res[s]
    max_row=max(ow.max_row, rw.max_row)
    max_col=max(ow.max_column, rw.max_column)
    for r in range(1,max_row+1):
        for c in range(1,max_col+1):
            oc, rc = ow.cell(r,c), rw.cell(r,c)
            if oc.style_id != rc.style_id or oc.number_format != rc.number_format:
                errors.append(f'style changed {s}!{rc.coordinate}: style_id {oc.style_id}->{rc.style_id}, numfmt {oc.number_format}->{rc.number_format}')
ws=res['Task']
ranges = ['H12:L17','H19:L24','H26:L31','H35:L40','H42:L47','H50:L50']
count=0
bad=[]
for rng in ranges:
    for row in ws[rng]:
        for cell in row:
            count += 1
            if not (isinstance(cell.value, str) and cell.value.startswith('=')):
                bad.append(f'{cell.coordinate}:{cell.value!r}')
print('sheetnames:', res.sheetnames)
print('target_formula_count:', count)
print('non_formula_targets:', bad)
print('xlsx_zip_valid:', zipfile.is_zipfile(out), 'testzip:', zipfile.ZipFile(out).testzip() if zipfile.is_zipfile(out) else None)
print('all_cell_style_ids_match_original:', not errors)
print('formula samples:')
for addr in ['H12','I12','L17','H19','H26','H35','I36','L40','H42','H45','H46','H50','L50']:
    print(f'  {addr}={ws[addr].value}')
if errors:
    print('\n'.join(errors[:20]))
    raise SystemExit(1)
if bad:
    raise SystemExit(1)
orig.close(); res.close()
